<?php
namespace App\Services;use Illuminate\Support\Facades\Http;use RuntimeException;
class WhatsAppGateway{public function sendMessage(string $n,string $m):void{$r=Http::acceptJson()->timeout(15)->post(rtrim(config('services.whatsapp.url'),'/').'/send-message',['api_key'=>config('services.whatsapp.api_key'),'sender'=>config('services.whatsapp.sender'),'number'=>$n,'message'=>$m]);if($r->failed())throw new RuntimeException('WhatsApp message failed: '.$r->body());}public function sendPdf(string $n,string $c,string $u):void{$r=Http::acceptJson()->timeout(20)->post(rtrim(config('services.whatsapp.url'),'/').'/send-media',['api_key'=>config('services.whatsapp.api_key'),'sender'=>config('services.whatsapp.sender'),'number'=>$n,'media_type'=>'pdf','caption'=>$c,'url'=>$u]);if($r->failed())throw new RuntimeException('WhatsApp media failed: '.$r->body());}}
